package app.cryptoresearch.mobile;
import android.content.Intent;import android.os.Looper;import android.widget.*;import android.view.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28) @LooperMode(LooperMode.Mode.PAUSED)
public class NativeUiTest {
 org.robolectric.android.controller.ActivityController<MainActivity> controller;MainActivity app;
 @Before public void start(){controller=Robolectric.buildActivity(MainActivity.class);app=controller.create().start().resume().get();}
 @After public void stop(){controller.pause().stop().destroy();}
 @Test public void startsOffline(){assertFalse(app.requested);assertNotNull(app.root);assertEquals(4,app.nav.getChildCount());assertTrue(app.price.getText().toString().contains("—"));}
 @Test public void navigation(){for(int i=0;i<4;i++){app.nav.getChildAt(i).performClick();assertEquals(i,app.tab);assertTrue(app.body.getChildCount()>0);}}
 @Test public void favoritesPersist(){app.favorites.add("SOL");app.selected="SOL";app.save();assertTrue(app.prefs.getStringSet("favorites",java.util.Collections.emptySet()).contains("SOL"));assertEquals("SOL",app.prefs.getString("coin",""));}
 @Test public void publicFrames(){app.requested=true;long n=System.currentTimeMillis();app.receive("{\"code\":\"KRW-BTC\",\"trade_price\":142800,\"trade_timestamp\":"+n+",\"signed_change_rate\":0.01}",true,app.generation);app.receive("{\"data\":{\"s\":\"BTCUSDT\",\"c\":\"100\",\"E\":"+n+"}}",false,app.generation);shadowOf(Looper.getMainLooper()).idle();assertEquals(142800,app.quotes.get("BTC").krw,0.001);assertEquals(2,app.premium("BTC",n,1400),1e-8);app.requested=false;}
 @Test public void rejectsOldGeneration(){app.requested=true;app.receive("{\"code\":\"KRW-BTC\",\"trade_price\":1,\"trade_timestamp\":1800000000000}",true,app.generation-1);shadowOf(Looper.getMainLooper()).idle();assertTrue(Double.isNaN(app.quotes.get("BTC").krw));app.requested=false;}
 @Test public void backgroundStopsSockets(){app.requested=false;controller.pause().stop();assertFalse(app.active);assertNull(app.up);assertNull(app.bin);controller.start().resume();}
 @Test public void reportAndSettings(){app.tab=2;app.build();assertTrue(app.research.contains("Python"));app.tab=3;app.build();assertTrue(app.body.getChildCount()>=2);}
 @Test public void csvImportRunsNativeEngine()throws Exception {StringBuilder csv=new StringBuilder("timestamp,open,high,low,close,volume\n");for(int i=0;i<32;i++){double o=i==31?110:100,h=i>=30?110:100,c=i>=30?110:100,l=i==31?110:100;csv.append(java.time.Instant.ofEpochMilli(1800000000000L+i*60000)).append(',').append(o).append(',').append(h).append(',').append(l).append(',').append(c).append(",0\n");}java.io.File file=new java.io.File(app.getCacheDir(),"test-bars.csv");try(java.io.FileOutputStream out=new java.io.FileOutputStream(file)){out.write(csv.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}app.tab=2;app.build();app.onActivityResult(41,android.app.Activity.RESULT_OK,new Intent().setData(android.net.Uri.fromFile(file)));for(int i=0;i<40&&!app.research.contains("매수 1 / 매도 1");i++){Thread.sleep(25);shadowOf(Looper.getMainLooper()).idle();}assertTrue(app.research,app.research.contains("매수 1 / 매도 1"));assertNotNull(app.strategyReport);org.json.JSONObject report=new org.json.JSONObject(new String(app.strategyReport,java.nio.charset.StandardCharsets.UTF_8));org.json.JSONArray curve=report.getJSONArray("equity_curve");assertEquals(32,curve.length());assertEquals(report.getDouble("ending_equity"),curve.getJSONObject(31).getDouble("equity"),0.000001);assertEquals(2,report.getJSONArray("fill_records").length());assertTrue(report.getDouble("total_fees")>0);assertTrue(new ResearchAnalyticsView(app,app.strategyReport).getChildCount()>5);}
 @Test public void syntheticButtonBuildsAnalytics()throws Exception{app.tab=2;app.build();View b=app.root.findViewWithTag("run-demo");assertNotNull(b);b.performClick();assertTrue(app.research.contains("합성 테스트"));org.json.JSONObject j=new org.json.JSONObject(new String(app.strategyReport,java.nio.charset.StandardCharsets.UTF_8));assertEquals(999800.1998501,j.getDouble("ending_equity"),0.000001);assertEquals(32,j.getJSONArray("equity_curve").length());}
 @Test public void displaySamplingKeepsExtrema()throws Exception{org.json.JSONObject report=new org.json.JSONObject();org.json.JSONArray points=new org.json.JSONArray();for(int i=0;i<2000;i++)points.put(new org.json.JSONObject().put("bar_timestamp_ms",i*60000L).put("equity",i==887?500:i==1179?1400:1000));report.put("equity_curve",points);ResearchAnalyticsView v=new ResearchAnalyticsView(app,report.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));assertTrue(v.drawIndices.size()<=602);assertTrue(v.drawIndices.contains(887));assertTrue(v.drawIndices.contains(1179));}
}
